// Feel free to change the data structures generated by AI.

#define MAX_SYSCALLS 1024
#define TOP_N 5
#define LINE_LEN 1024

extern char **environ;

typedef struct {
    char name[64];
    double time;
} syscall_stat;

typedef struct {
    syscall_stat stats[MAX_SYSCALLS];
    int count;
    double total_time;
} syscall_stats;

void printUsage() {
    printf("Usage:\n");
}

int parse_strace_line(char *line, char *syscall_name, double *time) {

    char *line_start = line;
    char *paren = strchr(line_start, '(');
	if (paren == 0) return 0;
	line[strcspn(line, "\r\n")] = '\0';

	size_t syscall_name_len = (size_t) (paren - line_start);
	if(syscall_name_len==0|syscall_name_len>=64)  return -1;

    //syscall_name和”(“之间还可能存在空格
    while (syscall_name_len > 0 && isspace((unsigned char) line_start[syscall_name_len - 1])) syscall_name_len--;
    //复制syscall的name
    memcpy(syscall_name, line_start, syscall_name_len);
	syscall_name[syscall_name_len] = '\0';

//        char *line_end =
    char *paren_angle_left = strrchr(line_start, '<');
    char *paren_angle_right = strrchr(line_start, '>');
	if (!paren_angle_left || !paren_angle_right || paren_angle_right <= paren_angle_left) return 0;
//        size_t syacall_time_len =(size_t)paren_angle_right-paren_angle_left;

    char *end = NULL;
    double syscall_time = strtod(paren_angle_left + 1, &end);
	if (paren_angle_right != end) return 0;
    line[strcspn(line, "\r\n")] = '\0';
    for (char *p = paren_angle_left; *p; p++) {
		if (isspace((unsigned char) *p)) return 0;
    }

   *time = syscall_time;
	return 1;
}

void add_syscall(syscall_stats *stats, const char *name, double time) {
//    stats->stats->name==name,
    stats->total_time += time;

//	for (int i = 0; i < count+1; ++i) {
//		if(strcmp(stats->stats[count]->name,name)!=0){
//			stats->count++;
//			stats->stats[count]->name=name;
//			stats->stats[count]->time=time;
//		}else{
//			stats->stats[count]->time+=time;
//		}
//	}
//    memcpy(stats->stats[count]->name, name, strlen(name));
//    stats->stats[count]->time = time;
//    stats->count++;

	for (int i = 0; i < stats->count; ++i) {
		if(strcmp(stats->stats[i].name,name)==0){
			stats->stats[i].time+=time;
			return;
		}
	}

	if(stats->count>=MAX_SYSCALLS)  return;

	int idx = stats->count;
	memcpy(stats->stats[idx].name, name, strlen(name));
	stats->stats[idx].name[strlen(name)]='\0';
	stats->stats[idx].time=time;
	stats->count++;
}

int cmp(const void *a,const void*b){
//	if((double)(*a)-(double)(*b)>0) return 1;
//	if((double)(*a)-(double)(*b)<0) return -1;
//	return 0;
	const syscall_stat *x=a,*y=b;
	if(x->time<y->time)  return 1;
	if(x->time>y->time)  return -1;
	return 0;
}
