void print_top_syscalls(syscall_stats *stats, int n) {
//	syscall_stats tmp_stats;
//	qsort(tmp_stats.stats,sizeof (tmp_stats.stats->time),cmp)
	qsort(stats->stats,stats->count,sizeof (stats->stats[0]),cmp);
	int len =stats->count<n?stats->count:n;
	for (int i = 0; i < len; ++i) {
		int ratio = stats->stats[i].time*100.0/stats->total_time;
		printf("%s (%d%%)\n", stats->stats[i].name, ratio);
	}

}


